import numpy as np, json, sys, time
from engine import EV,BP
checks=['bureau','income','bank']
def norm(v):
    s=v.sum();return v/s if s>1e-12 else np.ones(6)/6
def children(b,c):
    out=[]
    for ob in range(6):
        w=b*BP[c][:,ob]; pr=w.sum()
        if pr>1e-12: out.append((pr,ob,norm(w)))
    return out
def best_action(p,k,roundn=3):
    memo={}
    def exact(b,kk_):
        b=norm(np.asarray(b,float))
        key=(kk_,)+tuple(np.round(b,roundn))
        v=memo.get(key)
        if v is not None: return v
        stop=max(0.0,b@EV)
        if kk_==0:
            memo[key]=stop;return stop
        best=stop
        for c in checks:
            val=-20.0
            for pr,ob,w in children(b,c):
                val+=pr*exact(w,kk_-1)
            if val>best: best=val
        memo[key]=best
        return best
    b=norm(np.asarray(p,float))
    stop=max(0.0,b@EV)
    if k==0: return ('stop',stop),{}
    actvals={'stop':stop}
    for c in checks:
        val=-20.0
        for pr,ob,w in children(b,c):
            val+=pr*exact(w,k-1)
        actvals[c]=val
    bestact=max(actvals,key=actvals.get)
    return (bestact,actvals[bestact]),actvals

if __name__=='__main__':
    p=np.array(json.loads(sys.argv[1]));k=int(sys.argv[2])
    (a,v),av=best_action(p,k)
    print(json.dumps({'action':a,'value':v,'all':av,'EVapp':float(norm(p)@EV)}))
